import './style.css';
import '@near-wallet-selector/modal-ui-js/styles.css';
import { setupWalletSelector } from '@near-wallet-selector/core';
import { setupModal } from '@near-wallet-selector/modal-ui-js';
import { setupMyNearWallet } from '@near-wallet-selector/my-near-wallet';
import { TestnetRPC,validContract,formatNear,usdToNanos,formatUsdNanos } from './chain.js';
import { StakingCatalog } from './staking.js';
import { requestFreeze,requestRefund,refundResolution,launchActions,orderAction,submitActions,functionCall,aiPolicy } from './wallet.js';
import { newRecordKey,encrypt,decrypt,sealKey,publicKeyId,validateEnvelope,digest } from './crypto.js';
const $=s=>document.querySelector(s), rpc=new TestnetRPC();let current=null,selected=null,selector=null,task=null,epoch=0,lookupEpoch=0,formEpoch=0,orderEpoch=0,launchDraft=null,orderDraft=null,refundRevision=0,refundBusy=false;
const text=(id,value)=>$(id).textContent=String(value??'—');
function message(msg,bad=false){text('#message',msg);$('#message').className=bad?'error':'muted';}
function invalidate(){$('#order-quote').hidden=true;epoch++;lookupEpoch++;formEpoch++;orderEpoch++;launchDraft=null;orderDraft=null;current=null;task=null;$('#download-launch-key').disabled=true;$('#sign-launch').disabled=true;$('#download-order-key').disabled=true;$('#sign-order').disabled=true;$('#decrypted-report').hidden=true;text('#decrypted-report','');$('#job-key').value='';$('#job-recovery').value='';$('#summary').hidden=true;$('#freeze').disabled=true;$('#unfreeze').disabled=true;$('#export').disabled=true;$('#task').hidden=true;$('#decrypt-report').disabled=true;text('#task-summary','');refundRevision++;updateRefundState();}
$('#contract').addEventListener('input',invalidate);
$('#inspect').addEventListener('submit',async e=>{e.preventDefault();invalidate();const token=epoch,id=$('#contract').value.trim();$('#network').textContent='READING';try{const value=await rpc.inspect(id);if(epoch!==token||$('#contract').value.trim()!==id)return;current=value;$('#summary').hidden=false;text('#network','TESTNET VIEW');text('#owner',value.treasury.owner);text('#frozen',value.treasury.frozen?'FROZEN':'ACTIVE');for(const k of ['cash','escrow','committed','revenue','paid'])text('#'+k,formatNear(value.treasury[k]));text('#reserve-total',formatNear(value.treasury.reserve));try{const free=BigInt(value.treasury.cash)-BigInt(value.treasury.reserve)-BigInt(value.treasury.committed)-BigInt(value.treasury.withdrawing||'0');text('#available',formatNear(String(free>0n?free:0n)));}catch{text('#available','Unavailable');}text('#observed-hash','RPC-reported code hash: '+value.code_hash);text('#block',`Final block ${value.block.height} · ${value.block.hash} · ${value.contract}`);text('#policy',JSON.stringify(Object.fromEntries(['supplier','price','fee','reserve','perJob','daily'].map(k=>[k,value.treasury[k]??null])),null,2));text('#company',JSON.stringify({company:value.company,treasury:value.treasury},null,2));rpc.view(id,'company_solvency',{},value.block.hash).then(v=>{if(epoch===token&&current===value)text('#solvency',`Account balance ${formatNear(v.account_balance)} · minimum liabilities and storage backing ${formatNear(v.minimum_account_balance)} · shortfall ${formatNear(v.shortfall)}.`)}).catch(()=>{if(epoch===token)text('#solvency','Account backing view unavailable; inspect before funding.');});rpc.view(id,'ai_policy',{},value.block.hash).then(v=>{if(epoch===token&&current===value)text('#ai-current',`Current on-chain policy: ${v.enabled?'enabled':'disabled'} · selected ${v.selected_model} · per call ${formatUsdNanos(v.per_call_nanos)}, daily ${formatUsdNanos(v.daily_nanos)}, lifetime ${formatUsdNanos(v.lifetime_nanos)}. Provider charges are separate.`)}).catch(()=>{if(epoch===token)text('#ai-current','AI policy view unavailable.');});text('#history','First page of task IDs: '+(value.history.items.join(', ')||'none'));message('Expected company views were returned. Verify the code hash independently before signing.');updateWallet();}catch(err){if(epoch!==token)return;text('#network','UNAVAILABLE');message(err.message,true);}});
async function initializeWallet(){if(selector)return selector;selector=await setupWalletSelector({network:'testnet',modules:[setupMyNearWallet()]});if(selector.options.network.networkId!=='testnet')throw Error('Wallet network mismatch.');selector.store.observable.subscribe(updateWallet);return selector;}
function updateWallet(){const accounts=selector?.store.getState().accounts||[],previous=selected;selected=accounts.find(a=>a.active)?.accountId||null;if(previous!==selected)refundRevision++;text('#wallet-status',selected?'Connected: '+selected+' · wallet approval required for transactions.':'No wallet connected. Never enter a seed phrase or private key here.');const allowed=!!(selected&&current&&selected===current.treasury.owner);$('#freeze').disabled=!allowed;$('#unfreeze').disabled=!allowed;updateRefundState();}
$('#connect').addEventListener('click',async()=>{const token=epoch,context=current;try{if(!context)throw Error('Inspect the intended contract first.');const s=await initializeWallet();if(epoch!==token||current!==context)return;setupModal(s,{contractId:context.contract}).show();updateWallet();}catch(err){if(epoch===token)text('#wallet-status',err.message);}});
async function freeze(frozen){const token=epoch,account=selected,context=current;try{if(!context||!account)throw Error('Inspect and connect first.');const id=context.contract,expected=$('#expected-hash').value.trim();const latest=await rpc.inspect(id);if(epoch!==token||selected!==account||$('#contract').value.trim()!==id)throw Error('Contract or account changed; inspect again.');if(!confirm(`Ask your testnet wallet to ${frozen?'freeze':'unfreeze'} ${id}? No deposit; testnet gas applies.`))return;const wallet=await selector.wallet();if(epoch!==token||selected!==account||$('#contract').value.trim()!==id)throw Error('Contract or account changed; inspect again.');const result=await requestFreeze({wallet,accountId:account,owner:latest.treasury.owner,contract:id,expectedCodeHash:expected,actualCodeHash:latest.code_hash,frozen});if(epoch!==token)return;text('#wallet-status',result?'Wallet returned a transaction outcome. Refresh state and verify finality.':'Wallet redirected or returned no outcome. Verify chain state before retrying.');}catch(err){if(epoch===token)text('#wallet-status',err.message);}}
$('#freeze').addEventListener('click',()=>freeze(true));$('#unfreeze').addEventListener('click',()=>freeze(false));
$('#task-id').addEventListener('input',()=>{lookupEpoch++;task=null;$('#export').disabled=true;$('#task').hidden=true;$('#decrypt-report').disabled=true;$('#decrypted-report').hidden=true;text('#decrypted-report','');$('#job-key').value='';$('#job-recovery').value='';text('#task-summary','');refundRevision++;updateRefundState();});
$('#lookup').addEventListener('submit',async e=>{e.preventDefault();const lookup=++lookupEpoch;task=null;$('#export').disabled=true;$('#task').hidden=true;$('#decrypt-report').disabled=true;$('#decrypted-report').hidden=true;text('#task-summary','');refundRevision++;updateRefundState();const token=epoch,context=current;try{if(!context)throw Error('Inspect the contract first.');const id=$('#task-id').value.trim();if(!/^[A-Za-z0-9_-]{1,64}$/.test(id))throw Error('Invalid task ID.');const block=await rpc.finalBlock(),value=await rpc.view(context.contract,'company_task',{id},block.hash);if(epoch!==token||lookupEpoch!==lookup||current!==context)return;if(!value)throw Error('Task not found.');let job=value.job_id?await rpc.view(context.contract,'job',{id:value.job_id},block.hash):null;if(epoch!==token||lookupEpoch!==lookup||current!==context)return;const labels={pending_review:'Reviewing scope',queued:'Queued',blocked:'Blocked by policy or reserve',hired:'Specialist hired',attested:'Report attested',archived:'Archived'};const financial={escrowed:'Service payment in escrow; not revenue.',accepted:'Service payment in escrow; specialist fee committed.',settled:'Service payment settled as revenue; specialist fee committed.',paying:'Service payment settled; specialist payment pending.',paid:'Service payment settled and specialist paid.',refunding:'Service refund pending; storage fees are nonrefundable.',refunded:'Service payment refunded; storage fees are nonrefundable.'};text('#task-summary',`${labels[value.status]||value.status||'Unknown'} · ${job?(financial[job.status]||'Job status: '+job.status):'No linked job.'} ${value.encrypted_evidence?'Encrypted report available below.':'Report not yet available.'}`);task={network:'testnet',contract:context.contract,block,task_id:id,job,record:value};text('#task',JSON.stringify(task,null,2));$('#task').hidden=false;$('#export').disabled=false;$('#decrypt-report').disabled=!(value.encrypted_evidence&&value.evidence_hash);updateRefundState();}catch(err){if(epoch!==token||lookupEpoch!==lookup||current!==context)return;text('#task',err.message);$('#task').hidden=false;}});
$('#export').addEventListener('click',()=>{if(!task)return;const url=URL.createObjectURL(new Blob([JSON.stringify(task,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='proof-work-encrypted-task.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

// Testnet company setup and orders. Private record keys remain in memory only.
const fields=['supplier','price','fee','reserve','per-job','daily','funding','backing','slots','mission','goal','target','worker-key'];
function yocto(value){if(typeof value!=='string'||value.length>65||!/^(0|[1-9]\d*)(?:\.\d{1,24})?$/.test(value))throw Error('Use a nonnegative NEAR amount with at most 24 decimal places.');const [a,b='']=value.split('.');let n=BigInt(a)*10n**24n+BigInt((b+'0'.repeat(24)).slice(0,24));if(n>=2n**128n)throw Error('Amount exceeds contract range.');return n.toString();}
function approvedTarget(raw){let u;try{u=new URL(raw)}catch{throw Error('Enter a valid fixture base URL.');}if(raw.length>200||u.protocol!=='https:'||!u.hostname.includes('.')||u.hostname.endsWith('.local')||u.hostname.endsWith('.internal')||/^[0-9.]+$/.test(u.hostname)||u.username||u.password||u.search||u.hash||u.href!==raw||!u.pathname.endsWith('/')||!/^\/(?:[A-Za-z0-9_-]+\/)*$/.test(u.pathname))throw Error('Use an HTTPS fixture base URL with simple path segments and a trailing slash.');return u.href;}
function policyForm(){let supplier=$('#supplier').value.trim();if(!validContract(supplier))throw Error('Use a valid testnet supplier account.');let policy={supplier,price:yocto($('#price').value.trim()),fee:yocto($('#fee').value.trim()),reserve:yocto($('#reserve').value.trim()),perJob:yocto($('#per-job').value.trim()),daily:yocto($('#daily').value.trim())};if(BigInt(policy.price)===0n||BigInt(policy.fee)===0n||BigInt(policy.fee)>BigInt(policy.perJob))throw Error('Price and fee must be positive and fee must fit the per-job limit.');return policy;}
function saveKey(label,id,key,contract,intent){const file=JSON.stringify({version:1,network:'testnet',contract,id,record_key:key,intent,notice:'Keep this private; required for local decryption.'},null,2),url=URL.createObjectURL(new Blob([file],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=label+'-'+id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function needsWallet(ownerOnly=true){if(!current||!selected||!selector)throw Error('Inspect a company and connect a testnet wallet first.');if(ownerOnly&&selected!==current.treasury.owner)throw Error('Connect the contract owner wallet.');if($('#expected-hash').value.trim()!==current.code_hash)throw Error('Enter the independently verified matching contract code hash.');}
async function fresh(context,token){const latest=await rpc.inspect(context.contract);if(epoch!==token||current!==context||selected===null)throw Error('Selection changed; review again.');if($('#expected-hash').value.trim()!==latest.code_hash||latest.code_hash!==context.code_hash)throw Error('Contract code hash changed or is not verified.');return latest;}
async function extras(context){const b=context.block.hash;return Promise.all([rpc.view(context.contract,'execution_profile',{},b),rpc.view(context.contract,'company_order_quote',{},b)]);}
fields.forEach(id=>$('#'+id).addEventListener('input',()=>{formEpoch++;launchDraft=null;$('#sign-launch').disabled=true;$('#download-launch-key').disabled=true;}));
$('#prepare-launch').addEventListener('click',async()=>{const context=current,token=epoch,account=selected,revision=formEpoch;try{needsWallet();if(localStorage.getItem('proofwork-testnet-pending-launch'))throw Error('A previous launch is unresolved. Inspect chain state before preparing another.');const latest=await fresh(context,token);if(selected!==account||latest.company.company_storage_reserve!=='0')throw Error('Launch requires a fresh unconfigured company.');const existing=await rpc.view(context.contract,'execution_profile',{},latest.block.hash);if(existing!==null)throw Error('Execution profile already exists; inspect it before proceeding.');if(!$('#mission').value.trim()||!$('#goal').value.trim()||new TextEncoder().encode($('#mission').value).length>2000||new TextEncoder().encode($('#goal').value).length>2000)throw Error('Mission and goal must each contain 1–2000 UTF-8 bytes.');const slots=Number($('#slots').value);if(!Number.isSafeInteger(slots)||slots<1||slots>10)throw Error('Choose 1–10 storage slots.');const policy=policyForm(),funding=yocto($('#funding').value.trim()),backing=yocto($('#backing').value.trim()),target=approvedTarget($('#target').value.trim()),pem=$('#worker-key').value,workerId=await publicKeyId(pem),key=newRecordKey();if(BigInt(funding)>100n*10n**24n||BigInt(backing)>100n*10n**24n)throw Error('Funding exceeds the 100 testnet NEAR limit.');const [idea,goal,sealed,quote]=await Promise.all([encrypt($('#mission').value,key),encrypt($('#goal').value,key),sealKey(key,pem,workerId),rpc.view(context.contract,'company_storage_quote',{blocks:1},latest.block.hash)]);if(epoch!==token||selected!==account||current!==context||formEpoch!==revision)throw Error('Selection or form changed; review again.');const fundingId='fund-'+crypto.randomUUID().replaceAll('-','');const profile={worker_public_key:pem,worker_key_id:workerId,mission_sealed_key:sealed,profile:'website-qa-v1',target_origin:target},mission={idea_hash:idea.hash,goal_hash:goal.hash,encrypted_idea:idea.envelope,encrypted_goal:goal.envelope};const storage=quote.required_deposit;if(!/^[1-9]\d{0,38}$/.test(storage))throw Error('Invalid storage quote.');const actions=launchActions({policy,mission,profile,storage,extraBlocks:slots-1,funding,backing,fundingId});launchDraft={context,token,account,revision,key,downloaded:false,policy,mission,profile,storage,slots,funding,backing,fundingId,actions};$('#download-launch-key').disabled=false;text('#launch-status',`Review: ${slots} storage blocks × ${formatNear(storage)}; funding ${formatNear(funding)}; backing ${formatNear(backing)}; target ${target}; worker key ${workerId}. Gas additional. Download the recovery key before wallet approval.`);}catch(e){text('#launch-status',e.message);}});
$('#download-launch-key').addEventListener('click',()=>{if(!launchDraft)return;saveKey('company-recovery',launchDraft.fundingId,launchDraft.key,launchDraft.context.contract,{fundingId:launchDraft.fundingId,idea_hash:launchDraft.mission.idea_hash,goal_hash:launchDraft.mission.goal_hash,worker_key_id:launchDraft.profile.worker_key_id,mission_sealed_key:launchDraft.profile.mission_sealed_key,target:launchDraft.profile.target_origin,policy:launchDraft.policy,storage:launchDraft.storage,slots:launchDraft.slots,funding:launchDraft.funding,backing:launchDraft.backing});launchDraft.downloaded=true;$('#sign-launch').disabled=false;});
$('#sign-launch').addEventListener('click',async e=>{const button=e.currentTarget,d=launchDraft;button.disabled=true;try{if(!d||!d.downloaded)throw Error('Review and download the recovery key first.');needsWallet();const latest=await fresh(d.context,d.token);if(selected!==d.account||formEpoch!==d.revision||launchDraft!==d||latest.company.company_storage_reserve!=='0'||await rpc.view(d.context.contract,'execution_profile',{},latest.block.hash)!==null)throw Error('Company state changed; review launch again.');const q=await rpc.view(d.context.contract,'company_storage_quote',{blocks:1},latest.block.hash);if(q.required_deposit!==d.storage)throw Error('Storage quote changed; review again.');if(!confirm(`Submit ${d.actions.length} owner actions to ${d.context.contract}? Storage ${formatNear(String(BigInt(d.storage)*BigInt(d.slots)))}; funding ${formatNear(d.funding)}; backing ${formatNear(d.backing)}; gas extra.`))return;const pending={contract:d.context.contract,fundingId:d.fundingId,idea_hash:d.mission.idea_hash,goal_hash:d.mission.goal_hash,worker_key_id:d.profile.worker_key_id,mission_sealed_key:d.profile.mission_sealed_key,target:d.profile.target_origin,policy:d.policy,storage:d.storage,slots:d.slots,funding:d.funding,backing:d.backing};const wallet=await selector.wallet();if(epoch!==d.token||current!==d.context||selected!==d.account||formEpoch!==d.revision||launchDraft!==d)throw Error('Selection changed; review launch again.');localStorage.setItem('proofwork-testnet-pending-launch',JSON.stringify(pending));await submitActions({wallet,accountId:d.account,owner:latest.treasury.owner,contract:d.context.contract,expectedCodeHash:$('#expected-hash').value.trim(),actualCodeHash:latest.code_hash,actions:d.actions});text('#launch-status','Wallet request submitted or redirected. Inspect finalized chain state before any retry; launch pending remains recorded.');}catch(err){text('#launch-status',err.message);}finally{button.disabled=!launchDraft?.downloaded;}});
$('#reconcile-launch').addEventListener('click',async()=>{try{if(!current)throw Error('Inspect the same contract first.');const p=JSON.parse(localStorage.getItem('proofwork-testnet-pending-launch')||'null');if(!p||p.contract!==current.contract)throw Error('No pending launch for this contract.');const context=current,token=epoch,latest=await rpc.inspect(context.contract),profile=await rpc.view(context.contract,'execution_profile',{},latest.block.hash);let funded=p.funding==='0'?true:(await rpc.view(context.contract,'funding_operation',{id:p.fundingId},latest.block.hash))===p.funding;let backed=p.backing==='0'?true:(await rpc.view(context.contract,'backing_operation',{id:'backing-'+p.fundingId},latest.block.hash))===p.backing;let op=p.slots===1?null:await rpc.view(context.contract,'company_storage_operation',{id:'storage-'+p.fundingId},latest.block.hash);let stored=p.slots===1?true:(op?.blocks===p.slots-1&&op?.amount===String(BigInt(p.storage)*BigInt(p.slots-1)));if(epoch!==token||current!==context)return;if(latest.company.idea_hash===p.idea_hash&&latest.company.goal_hash===p.goal_hash&&profile?.profile==='website-qa-v1'&&profile?.worker_key_id===p.worker_key_id&&profile?.mission_sealed_key===p.mission_sealed_key&&profile?.target_origin===p.target&&Object.entries(p.policy).every(([k,v])=>latest.treasury[k]===v)&&funded&&backed&&stored){localStorage.removeItem('proofwork-testnet-pending-launch');text('#launch-status','Finalized chain state matches the recorded launch. Keep the downloaded recovery key safe.');}else text('#launch-status','Launch effect is not fully proven by finalized state. Do not retry payment; inspect wallet transaction and chain receipts.');}catch(e){text('#launch-status',e.message);}});
$('#authorized').addEventListener('change',()=>{$('#order-quote').hidden=true;orderEpoch++;orderDraft=null;$('#sign-order').disabled=true;$('#download-order-key').disabled=true;});
$('#expected-hash').addEventListener('input',()=>{$('#order-quote').hidden=true;formEpoch++;orderEpoch++;launchDraft=null;orderDraft=null;$('#sign-launch').disabled=true;$('#download-launch-key').disabled=true;$('#sign-order').disabled=true;$('#download-order-key').disabled=true;});
$('#prepare-order').addEventListener('click',async()=>{const context=current,token=epoch,account=selected,revision=++orderEpoch;try{needsWallet(false);if(!$('#authorized').checked)throw Error('Confirm authorization to test the target.');if(localStorage.getItem('proofwork-testnet-pending-order'))throw Error('An earlier order is unresolved. Inspect it before creating another.');const latest=await fresh(context,token),[profile,quote]=await extras(latest);if(epoch!==token||current!==context||selected!==account)throw Error('Selection changed; review again.');if(latest.treasury.frozen)throw Error('Company is frozen.');if(!profile||profile.profile!=='website-qa-v1'||!Number.isSafeInteger(profile.version)||profile.version<1)throw Error('No supported execution profile is configured.');approvedTarget(profile.target_origin);if(!quote||['service_price','job_storage_contribution','task_storage_contribution','backing_contribution','storage_contribution','total_attached'].some(k=>typeof quote[k]!=='string'||!/^(0|[1-9]\d{0,38})$/.test(quote[k]))||BigInt(quote.storage_contribution)!==BigInt(quote.job_storage_contribution)+BigInt(quote.task_storage_contribution)+BigInt(quote.backing_contribution)||BigInt(quote.total_attached)!==BigInt(quote.service_price)+BigInt(quote.storage_contribution))throw Error('Invalid contract quote.');const key=newRecordKey(),id='job-'+crypto.randomUUID().replaceAll('-',''),taskId='task-'+crypto.randomUUID().replaceAll('-','');const [scope,sealed]=await Promise.all([encrypt(JSON.stringify({profile:'website-qa-v1',target:profile.target_origin,authorized:true,checks:['broken_links','image_alt']}),key),sealKey(key,profile.worker_public_key,profile.worker_key_id)]);if(epoch!==token||current!==context||selected!==account||orderEpoch!==revision||!$('#authorized').checked)throw Error('Selection changed; review again.');const args={id,task_id:taskId,scope_hash:scope.hash,encrypted_scope:scope.envelope,worker_sealed_key:sealed,worker_key_id:profile.worker_key_id,execution_profile_version:profile.version,approved_service_price:quote.service_price,approved_job_storage:quote.job_storage_contribution,approved_task_storage:quote.task_storage_contribution,approved_backing:quote.backing_contribution};orderDraft={context,token,account,revision,key,args,quote,target:profile.target_origin,downloaded:false};$('#download-order-key').disabled=false;text('#order-status',`Target ${profile.target_origin}. Download the recovery key before signing.`);text('#quote-service',`Service escrow: ${formatNear(quote.service_price)}. Refundable if declined or refunded; it is not revenue while in escrow.`);text('#quote-storage',`Nonrefundable even if declined: job storage ${formatNear(quote.job_storage_contribution)}, record storage ${formatNear(quote.task_storage_contribution)}, backing ${formatNear(quote.backing_contribution)}.`);text('#quote-total',`Total: ${formatNear(quote.total_attached)}. Testnet gas is additional.`);text('#quote-yocto',JSON.stringify(quote,null,2));$('#order-quote').hidden=false;}catch(e){text('#order-status',e.message);}});
$('#download-order-key').addEventListener('click',()=>{if(!orderDraft)return;saveKey('job-recovery',orderDraft.args.id,orderDraft.key,orderDraft.context.contract,{account:orderDraft.account,args:orderDraft.args,quote:orderDraft.quote});orderDraft.downloaded=true;$('#sign-order').disabled=false;});
$('#sign-order').addEventListener('click',async e=>{const button=e.currentTarget,d=orderDraft;button.disabled=true;try{if(!d||!d.downloaded||!$('#authorized').checked)throw Error('Review, authorize and download the recovery key first.');needsWallet(false);if(localStorage.getItem('proofwork-testnet-pending-order'))throw Error('An earlier order needs reconciliation.');const latest=await fresh(d.context,d.token),[profile,quote]=await extras(latest);if(selected!==d.account||orderEpoch!==d.revision||orderDraft!==d||!$('#authorized').checked||latest.treasury.frozen||profile?.version!==d.args.execution_profile_version||profile?.worker_key_id!==d.args.worker_key_id||profile?.target_origin!==d.target||quote.total_attached!==d.quote.total_attached||quote.service_price!==d.quote.service_price||quote.storage_contribution!==d.quote.storage_contribution||quote.job_storage_contribution!==d.quote.job_storage_contribution||quote.task_storage_contribution!==d.quote.task_storage_contribution||quote.backing_contribution!==d.quote.backing_contribution)throw Error('Quote, worker, company or account changed; review again.');if(!confirm(`Pay ${formatNear(quote.total_attached)} (${quote.total_attached} yoctoNEAR) to ${d.context.contract} for authorized QA? Only the service amount is refundable; job storage, record storage and backing are nonrefundable. Gas extra.`))return;const wallet=await selector.wallet();if(epoch!==d.token||current!==d.context||selected!==d.account||orderEpoch!==d.revision||orderDraft!==d||!$('#authorized').checked)throw Error('Selection changed; review order again.');const action=orderAction(d.args,quote.total_attached);localStorage.setItem('proofwork-testnet-pending-order',JSON.stringify({contract:d.context.contract,account:d.account,args:d.args,quote:d.quote}));await submitActions({wallet,accountId:d.account,contract:d.context.contract,expectedCodeHash:$('#expected-hash').value.trim(),actualCodeHash:latest.code_hash,actions:[action],ownerOnly:false});text('#order-status','Wallet request submitted or redirected. Inspect pending order before any retry.');}catch(err){text('#order-status',err.message);}finally{button.disabled=!orderDraft?.downloaded;}});
