// The funding catalog is a separate, read-only mainnet inspection. It never
// shares the testnet wallet/owner actions and never creates a staking action.
let stakingEpoch=0,stakingReport=null;
$('#staking-pin').addEventListener('input',()=>{stakingEpoch++;stakingReport=null;$('#staking-results').hidden=true;$('#export-staking').disabled=true;text('#staking-raw','');text('#staking-status','Code pin changed; inspect again before exporting a snapshot.');});
$('#inspect-staking').addEventListener('click',async()=>{
 const button=$('#inspect-staking'),revision=stakingEpoch,pin=$('#staking-pin').value.trim()||null;button.disabled=true;stakingReport=null;$('#staking-results').hidden=true;$('#export-staking').disabled=true;
 text('#staking-status','Reading one finalized mainnet block and its NEAR AI catalog. No wallet or paid call.');
 try{
  const report=await new StakingCatalog().inspect(pin);if(revision!==stakingEpoch||($('#staking-pin').value.trim()||null)!==pin)return;const body=$('#staking-prices');body.replaceChildren();
  for(const product of report.products)for(const price of product.prices){
   const row=document.createElement('tr');
   for(const value of [product.name+' / '+price.name,price.price_type+(price.billing_period?' · '+price.billing_period:''),formatNear(price.amount),price.metadata?.max_amount?formatNear(price.metadata.max_amount):'Not specified',product.status+' product / '+price.status+' price']){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}body.append(row);
  }
  text('#staking-status',`MAINNET READ ONLY · ${report.paused?'Contract paused':'Contract not paused'} · finalized block ${report.block.height}. ${report.independent_code_pin?'Independent code pin matched.':'Code identity is RPC-reported; no independent code pin supplied.'}`);
  text('#staking-identity',`${report.contract} · code ${report.code_hash} · block ${report.block.hash}`);
  text('#staking-storage',`Base registration ${formatNear(report.terms.min_storage_deposit)} · per-lock storage ${formatNear(report.terms.per_lock_storage_stake)} · unstaking settle setting ${report.terms.epoch_unstake_settle_epochs} epochs. Actual account storage and withdrawal timing require separate review.`);
  stakingReport=report;text('#staking-raw',JSON.stringify(report,null,2));$('#staking-results').hidden=false;$('#export-staking').disabled=false;
 }catch(error){if(revision===stakingEpoch)text('#staking-status',error.message);}
 finally{button.disabled=false;}
});
$('#export-staking').addEventListener('click',()=>{const pin=$('#staking-pin').value.trim()||null;if(!stakingReport||stakingReport.independent_code_pin!==(pin!==null)||(pin!==null&&pin!==stakingReport.code_hash))return;const url=URL.createObjectURL(new Blob([JSON.stringify(stakingReport,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='near-ai-read-only-catalog.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

// Customer-owned service refunds. This path never borrows owner authority and
// remains available while company spending is frozen.
const REFUND_PENDING='proofwork-testnet-pending-refund',REFUND_TX=/^[1-9A-HJ-NP-Za-km-z]{32,44}$/;
function readRefundIntent(){
 const raw=localStorage.getItem(REFUND_PENDING);if(raw===null)return null;
 if(raw.length>4096)throw Error('Stored refund intent is invalid; inspect wallet history before changing it.');
 let value;try{value=JSON.parse(raw);}catch{throw Error('Stored refund intent is invalid; inspect wallet history before changing it.');}
 const names=['version','network','contract','account','job_id','code_hash','started_block_height','started_block_hash','request_id','tx_hash'];
 if(!value||Object.keys(value).sort().join(',')!==names.sort().join(',')||value.version!==1||value.network!=='testnet'||!validContract(value.contract)||typeof value.account!=='string'||!/^(?=.{2,64}$)[a-z0-9]+(?:[._-][a-z0-9]+)*$/.test(value.account)||typeof value.job_id!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(value.job_id)||typeof value.code_hash!=='string'||!value.code_hash||value.code_hash.length>100||!Number.isSafeInteger(value.started_block_height)||value.started_block_height<0||typeof value.started_block_hash!=='string'||!value.started_block_hash||value.started_block_hash.length>100||typeof value.request_id!=='string'||!/^[A-Za-z0-9_-]{16,64}$/.test(value.request_id)||(value.tx_hash!==null&&(typeof value.tx_hash!=='string'||!REFUND_TX.test(value.tx_hash))))throw Error('Stored refund intent is invalid; inspect wallet history before changing it.');
 return {raw,value};
}
function updateRefundState(notice=null){
 const button=$('#request-refund');button.disabled=true;let status;
 try{
  const pending=readRefundIntent();
  if(refundBusy)status='Checking the refund request. No automatic retry is permitted.';
  else if(pending)status=`Unresolved refund for ${pending.value.job_id} at ${pending.value.contract}. Inspect it before another wallet request. A wallet error or escrow view alone does not prove failure.`;
  else if(!current||!task||task.contract!==current.contract||!task.job||!task.record?.job_id)status='Read a customer task to inspect service-refund eligibility.';
  else if(task.job.status!=='escrowed')status=`Job ${task.record.job_id} is ${task.job.status}; only unaccepted service escrow can be refunded. Storage and backing remain nonrefundable.`;
  else {
   status=`Refundable service escrow: ${formatNear(task.job.deposit)}. Nonrefundable storage/backing: ${formatNear(task.job.storage_contribution)}. Original customer: ${task.job.customer}.`;
   if(!selected||selected!==task.job.customer)status+=' Connect that original customer wallet.';
   else if($('#expected-hash').value.trim()!==current.code_hash)status+=' Verify the company code hash before signing.';
   else if(!navigator.locks?.request)status+=' This browser needs Web Locks for safe same-origin refund coordination.';
   else button.disabled=false;
  }
 }catch(error){status=error.message;}
 text('#refund-status',notice||status);
}
function currentRefund(context,token,loaded,lookup,account,revision){
 if(epoch!==token||current!==context||task!==loaded||lookupEpoch!==lookup||selected!==account||refundRevision!==revision||$('#contract').value.trim()!==context.contract||$('#expected-hash').value.trim()!==context.code_hash)throw Error('Contract, task, wallet or code pin changed; review the refund again.');
}
async function refundLock(operation){
 if(!navigator.locks?.request)throw Error('Use a secure-origin browser with Web Locks for customer refunds.');
 return navigator.locks.request('proofwork-testnet-customer-refund',{mode:'exclusive',ifAvailable:true},async lock=>{if(!lock)throw Error('Another browser tab is inspecting or submitting a refund.');return operation();});
}
$('#expected-hash').addEventListener('input',()=>{refundRevision++;updateRefundState();});
$('#refund-hash').addEventListener('input',()=>{refundRevision++;});
window.addEventListener('storage',event=>{if(event.key===REFUND_PENDING||event.key===null){refundRevision++;updateRefundState();}});
$('#request-refund').addEventListener('click',async()=>{
 if(refundBusy)return;refundBusy=true;updateRefundState();let notice;
 try{await refundLock(async()=>{
  needsWallet(false);if(readRefundIntent())throw Error('A previous refund remains unresolved; inspect it before another signature.');
  const context=current,token=epoch,loaded=task,lookup=lookupEpoch,account=selected,revision=refundRevision;
  if(!loaded?.job||loaded.contract!==context.contract||typeof loaded.record?.job_id!=='string')throw Error('Read the customer task before requesting a refund.');
  const jobId=loaded.record.job_id,latest=await fresh(context,token),job=await rpc.view(context.contract,'job',{id:jobId},latest.block.hash);
  currentRefund(context,token,loaded,lookup,account,revision);
  if(!job||job.customer!==account||job.customer!==loaded.job.customer||job.status!=='escrowed'||job.deposit!==loaded.job.deposit||job.storage_contribution!==loaded.job.storage_contribution)throw Error('Finalized customer, terms or job state changed; read the task again.');
  if(!confirm(`Request the service refund for ${jobId} from ${context.contract}?\nOnly ${formatNear(job.deposit)} service escrow returns to the original customer ${job.customer}.\n${formatNear(job.storage_contribution)} storage/backing stays nonrefundable. No deposit is attached; testnet gas applies.\nThis customer action is allowed even if company spending is frozen.`))return;
  const wallet=await selector.wallet();currentRefund(context,token,loaded,lookup,account,revision);
  if(readRefundIntent())throw Error('Another refund intent appeared; inspect it first.');
  const pending={version:1,network:'testnet',contract:context.contract,account,job_id:jobId,code_hash:latest.code_hash,started_block_height:latest.block.height,started_block_hash:latest.block.hash,request_id:crypto.randomUUID(),tx_hash:null},raw=JSON.stringify(pending);
  const result=await requestRefund({wallet,accountId:account,contract:context.contract,jobId,job,expectedCodeHash:$('#expected-hash').value.trim(),actualCodeHash:latest.code_hash,beforeSubmit:()=>{localStorage.setItem(REFUND_PENDING,raw);$('#refund-hash').value='';}});
  const tx=result?.transaction;if(localStorage.getItem(REFUND_PENDING)===raw&&tx?.signer_id===account&&tx?.receiver_id===context.contract&&typeof tx.hash==='string'&&REFUND_TX.test(tx.hash))localStorage.setItem(REFUND_PENDING,JSON.stringify({...pending,tx_hash:tx.hash}));
  notice='Refund wallet request submitted or redirected. Inspect pending refund for FINAL state before any retry; no refund is claimed complete yet.';
 });}catch(error){notice=error.message;}
 finally{refundBusy=false;updateRefundState(notice);}
});
$('#reconcile-refund').addEventListener('click',async()=>{
 if(refundBusy)return;refundBusy=true;updateRefundState();let notice;
 try{await refundLock(async()=>{
  const stored=readRefundIntent();if(!stored)throw Error('No unresolved refund intent is stored in this browser. Read the task for current status.');
  const p=stored.value,context=current,token=epoch,account=selected,revision=refundRevision;
  if(!context||context.contract!==p.contract||$('#expected-hash').value.trim()!==p.code_hash||context.code_hash!==p.code_hash)throw Error('Inspect the original company and independently verify the refund intent code hash first.');
  const typed=$('#refund-hash').value.trim();if(typed&&!REFUND_TX.test(typed))throw Error('Enter the exact wallet transaction hash, never a key.');if(typed&&p.tx_hash&&typed!==p.tx_hash)throw Error('The supplied hash differs from the wallet-returned refund hash.');
  const hash=typed||p.tx_hash;let outcome=null,transactionBlock=null;
  if(hash){
   outcome=await rpc.request('tx',{tx_hash:hash,sender_account_id:p.account,wait_until:'FINAL'});
   const executionHash=outcome?.transaction_outcome?.block_hash;if(typeof executionHash!=='string'||!REFUND_TX.test(executionHash))throw Error('Transaction execution block is not proven.');
   const block=await rpc.request('block',{block_id:executionHash});transactionBlock=block?.header;
   if(!transactionBlock||transactionBlock.hash!==executionHash||!Number.isSafeInteger(transactionBlock.height))throw Error('Transaction execution block is not proven.');
  }
  const latest=await rpc.inspect(context.contract);if(latest.code_hash!==p.code_hash||$('#expected-hash').value.trim()!==p.code_hash)throw Error('Refund contract code changed; verify independently before continuing.');const job=await rpc.view(context.contract,'job',{id:p.job_id},latest.block.hash);
  if(epoch!==token||current!==context||selected!==account||refundRevision!==revision||$('#refund-hash').value.trim()!==typed||localStorage.getItem(REFUND_PENDING)!==stored.raw)throw Error('Selection or refund intent changed; inspect again.');
  if(transactionBlock&&latest.block.height<transactionBlock.height)throw Error('Finalized company view predates the wallet transaction; inspect again.');
  const result=refundResolution({contract:p.contract,accountId:p.account,jobId:p.job_id,job,hash,outcome,startedBlockHeight:p.started_block_height,transactionBlock});
  if(['refunded','failed_retry_allowed','failed_not_refundable'].includes(result))localStorage.removeItem(REFUND_PENDING);
  if(task?.contract===context.contract&&task.record?.job_id===p.job_id){task={...task,block:latest.block,job};text('#task',JSON.stringify(task,null,2));text('#task-summary',`Job ${p.job_id}: ${job.status}. ${job.status==='refunded'?'Service escrow returned to the original customer.':'Read current service-refund eligibility below.'} Storage/backing is nonrefundable.`);}
  notice=result==='refunded'?`Finalized job ${p.job_id} is refunded: only service escrow returned; permanent storage/backing remains.`:result==='failed_retry_allowed'?'The exact refund transaction is FINAL and failed; current service escrow is still unaccepted. The intent is resolved. Review a new wallet request explicitly to retry.':result==='failed_not_refundable'?`The refund transaction is FINAL and failed; job ${p.job_id} is now ${job.status} and cannot use the customer refund path.`:'Refund remains unresolved or its transfer callback is not proven complete. No new signature is enabled. Use the exact wallet hash; ordinary errors and escrow views do not authorize retry.';
 });}catch(error){notice=error.message;}
 finally{refundBusy=false;updateRefundState(notice);}
});
updateRefundState();
